#!/usr/bin/env python3
"""Audit the pure-sheet orbit representative for loaded face BC."""
import json,subprocess,tempfile
from pathlib import Path
R=Path(__file__).resolve().parents[2];s=R/'research/voevodsky/check_cross_polytope_equivariant_top_trace_no_go.rs';e=Path(tempfile.gettempdir())/(s.stem+'.exe');subprocess.run(['rustc','--edition=2021','-D','warnings','-O',str(s),'-o',str(e)],check=True);x=json.loads(subprocess.check_output([str(e)],text=True))
checks={'pure_orbit2':x['face_orbits'][0]==2,'reflection_sign_geometric':x['geometric_face_reflection_sign']==-1,'orientation_twist':x['source_orientation_twist_sign']==-1,'loaded_face_even':x['loaded_face_reflection_sign']==1,'target_odd':x['loaded_target_reflection_sign']==-1,'unit_empty':x['primitive_top_value_one_solution']=='EMPTY','not_constructed':not x['odd_interior_column_geometrically_constructed']}
assert all(checks.values()),checks
out={'schema':'marici.voevodsky.CR1-pure-sheet-face-BC-representative.v1','action':'CR1QCOUN1a1_construct_pure_sheet_face_BC_representative','outcome':'--','obstruction':'after the source orientation twist, the pure-sheet face orbit is reflection-even while the loaded Q target is reflection-odd; no nonzero equivariant face map of the required character exists','ordinary_contribution':'2a','interpretation':'the pure-sheet faces can contribute only to the even boundary trace; the odd unit must come from the relative interior, not a pure-face BC representative','next_independent':'CR1QCOUN1a2_construct_mixed_sheet_face_BC_representative','metric_delta':{'active_face_BC_representatives':-1,'blocked_face_BC_representatives':1,'new_typed_interfaces':0,'pure_face_unit_candidates':0},'checks':checks,'passed':True};p=R/'research/voevodsky/results/CR1_pure_sheet_face_BC_representative.json';p.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({'passed':True,'outcome':'--','pure_orbit':2,'unit_candidates':0,'active_representatives':1,'next':out['next_independent']}))
